import Base
import ./asset.bend as Asset
import ./content.bend as Content
import ../deps/jonlib-png/png.bend as Png
import ../deps/jonlib-png/codec.bend as Codec

# Engine errors use bit 31. Native errno values retain their code and message.
def decoder_error(error:Codec.Error) -> Asset.Error:
  match error:
    case Codec.BadHeader{}:Asset.Error{2147483649,"PNG BadHeader"}
    case Codec.BadByte{}:Asset.Error{2147483650,"PNG BadByte"}
    case Codec.BadSize{}:Asset.Error{2147483651,"PNG BadSize"}
    case Codec.Truncated{}:Asset.Error{2147483652,"PNG Truncated"}
    case Codec.BadStream{}:Asset.Error{2147483653,"PNG BadStream"}

# Consume the affine tree in index order, constructing reusable words.
def array_words(array:Array<U32>,tail:List<&2,U32>) -> List<&2,U32>:
  match array:
    case ALeaf{value}:value <> tail
    case ANode{left,right}:array_words(left,array_words(right,tail))

def checked(image:Content.SourceImage,valid:Bool) -> Result<&2,&2,Asset.Error,Content.SourceImage>:
  match valid:
    case True{}:Done{image}
    case False{}:Fail{Asset.Error{2147483654,"PNG output violates image storage"}}

def picture(result:Result<&1,&1,Codec.Error,Codec.Picture>) -> Result<&2,&2,Asset.Error,Content.SourceImage>:
  match result:
    case Fail{error}:Fail{decoder_error(error)}
    case Done{Codec.Picture{+width,+height,_,pixels}}:
      +image:Content.SourceImage = Content.SourceImage{width,height,List.take(&2,U32,array_words(pixels,[]),Nat.mul(U32.to_nat(width),U32.to_nat(height)))}
      checked(image,Content.image_valid(image))

def decode(+bytes:List<&2,U32>) -> Result<&2,&2,Asset.Error,Content.SourceImage>:
  picture(Png.decode(bytes))

def exact(bytes:List<&2,U32>,complete:Bool) -> Result<&2,&2,Asset.Error,Content.SourceImage>:
  match complete:
    case True{}:decode(bytes)
    case False{}:Fail{Asset.Error{2147483655,"PNG file size changed or read was incomplete"}}

def read_result(result:Result<&1,&1,U32 & String,List<&2,U32>>,size:U32) -> Result<&2,&2,Asset.Error,Content.SourceImage>:
  match result:
    case Fail{(code,message)}:Fail{Asset.Error{code,message}}
    case Done{+bytes}:exact(bytes,Nat.is_eq(List.length(&2,U32,bytes),U32.to_nat(size)))

def read_closed(pair:File & Result<&1,&1,U32 & String,List<&2,U32>>,size:U32) -> IO(Result<&2,&2,Asset.Error,Content.SourceImage>):
  (file,result) = pair
  do IO<Result<&2,&2,Asset.Error,Content.SourceImage>>:
    File.close(file)
    return read_result(result,size)

def read_bounded(file:File,+size:U32,fits:Bool) -> IO(Result<&2,&2,Asset.Error,Content.SourceImage>):
  match fits:
    case False{}:
      do IO<Result<&2,&2,Asset.Error,Content.SourceImage>>:
        File.close(file)
        return Fail{Asset.Error{2147483651,"PNG encoded input exceeds 2097152 bytes"}}
    case True{}:
      do IO<Result<&2,&2,Asset.Error,Content.SourceImage>>:
        pair:File & Result<&1,&1,U32 & String,List<&2,U32>> <- File.read_bytes(file,U32.inc(size))
        read_closed(pair,size)

def read_sized(pair:File & Result<&1,&1,U32 & String,U32>) -> IO(Result<&2,&2,Asset.Error,Content.SourceImage>):
  match pair:
    case (file,Fail{(code,message)}):
      do IO<Result<&2,&2,Asset.Error,Content.SourceImage>>:
        File.close(file)
        return Fail{Asset.Error{code,message}}
    case (file,Done{+size}):read_bounded(file,size,U32.is_le(size,2097152))

def read_opened(result:Result<&1,&1,U32 & String,File>) -> IO(Result<&2,&2,Asset.Error,Content.SourceImage>):
  match result:
    case Fail{(code,message)}:IO.pure(Result<&2,&2,Asset.Error,Content.SourceImage>,Fail{Asset.Error{code,message}})
    case Done{file}:
      do IO<Result<&2,&2,Asset.Error,Content.SourceImage>>:
        pair:File & Result<&1,&1,U32 & String,U32> <- File.size(file)
        read_sized(pair)

def load(path:String) -> IO(Result<&2,&2,Asset.Error,Content.SourceImage>):
  do IO<Result<&2,&2,Asset.Error,Content.SourceImage>>:
    opened:Result<&1,&1,U32 & String,File> <- File.open(path,"r")
    read_opened(opened)
import Base
import ./components.bend as C

type Vertex is Data:
  Vertex{position:C.Vec3,color:C.Vec3}
type Mesh is Data:
  Mesh{vertices:List<&2,Vertex>,indices:List<&2,U32>}
type Material is Data:
  Basic{tint:C.Vec3}

def finite(x:F32) -> Bool:
  U32.is_ne(U32.and(F32.bits(x),2139095040),2139095040)

def vec_finite(v:C.Vec3) -> Bool:
  C.Vec3{x,y,z} = v
  finite(x) && finite(y) && finite(z)

def vertices_valid(vertices:List<&2,Vertex>) -> Bool:
  match vertices:
    case []:True{}
    case Vertex{p,c} <> rest:vec_finite(p) && vec_finite(c) && vertices_valid(rest)

def indices_valid(indices:List<&2,U32>,+count:U32) -> Bool:
  match indices:
    case []:True{}
    case i <> rest:U32.is_lt(i,count) && indices_valid(rest,count)

def mesh_fits(vertices:Nat,indices:Nat) -> Bool:
  Nat.is_le(vertices,699050n) && Nat.is_le(indices,3000000n)

def mesh_valid(mesh:Mesh) -> Bool:
  Mesh{+vertices,+indices} = mesh
  +vc = List.length(&2,Vertex,vertices)
  +ic = List.length(&2,U32,indices)
  mesh_fits(vc,ic) && U32.is_zero(U32.mod(U32.from_nat(ic),3)) && vertices_valid(vertices) && indices_valid(indices,U32.from_nat(vc))

def channel(+x:F32) -> Bool:
  finite(x) && F32.is_ge(x,0.0) && F32.is_le(x,1.0)

def material_valid(material:Material) -> Bool:
  Basic{C.Vec3{r,g,b}} = material
  channel(r) && channel(g) && channel(b)

# Structural conversion keeps white identity reducible for every F32 payload.
def float_bits(value:F32) -> U32:
  F32{bits} = value
  U32{bits}

def float_word(value:U32) -> F32:
  U32{bits} = value
  F32{bits}

def white() -> Material:
  Basic{C.Vec3{float_word(1065353216),float_word(1065353216),float_word(1065353216)}}

def tint_channel(+value:F32,+tint:F32) -> F32:
  Bool.pick(F32,U32.is_eq(float_bits(tint),1065353216),value,F32.mul(value,tint))

def tint(vertex:Vertex,material:Material) -> Vertex:
  Vertex{p,C.Vec3{r,g,b}} = vertex
  Basic{C.Vec3{x,y,z}} = material
  Vertex{p,C.Vec3{tint_channel(r,x),tint_channel(g,y),tint_channel(b,z)}}

def bake(vertices:List<&2,Vertex>,+material:Material) -> List<&2,Vertex>:
  match vertices:
    case []:[]
    case v <> rest:tint(v,material) <> bake(rest,material)

def same_vec(a:C.Vec3,b:C.Vec3) -> Bool:
  C.Vec3{x,y,z} = a
  C.Vec3{u,v,w} = b
  U32.is_eq(F32.bits(x),F32.bits(u)) && U32.is_eq(F32.bits(y),F32.bits(v)) && U32.is_eq(F32.bits(z),F32.bits(w))

def same_vertices(a:List<&2,Vertex>,b:List<&2,Vertex>) -> Bool:
  match a b:
    case [], []:True{}
    case Vertex{p,c} <> xs, Vertex{q,d} <> ys:same_vec(p,q) && same_vec(c,d) && same_vertices(xs,ys)
    case _, _:False{}

def same_indices(a:List<&2,U32>,b:List<&2,U32>) -> Bool:
  match a b:
    case [], []:True{}
    case x <> xs, y <> ys:U32.is_eq(x,y) && same_indices(xs,ys)
    case _, _:False{}

def same_mesh(a:Mesh,b:Mesh) -> Bool:
  Mesh{v,i} = a
  Mesh{w,j} = b
  same_vertices(v,w) && same_indices(i,j)

def same_material(a:Material,b:Material) -> Bool:
  Basic{x} = a
  Basic{y} = b
  same_vec(x,y)

type SourceImage is Data:
  SourceImage{width:U32,height:U32,pixels:List<&2,U32>}

# Positive dimensions and exact storage are source rules, independent of PNG.
def image_valid(image:SourceImage) -> Bool:
  SourceImage{+width,+height,+pixels} = image
  U32.is_gt(width,0) && U32.is_gt(height,0) && Nat.is_eq(List.length(&2,U32,pixels),Nat.mul(U32.to_nat(width),U32.to_nat(height)))
import Base
import ./image-decoder/common.bend as C

def command(program:String,args:List<String>) -> IO(Unit):
  do IO<Unit>:
    output:String <- C.command(program,args)
    IO.write(output)

def main() -> IO(Unit):
  do IO<Unit>:
    command("mkdir",["-p","build/image-comparison"])
    command("sha256sum",["-c","deps/jonlib-png/SHA256SUMS"])
    command("sha256sum",["-c","docs/verification/2026-11-04-image-decoder/corpus/SHA256SUMS"])
    command("bend",["tools/image-decoder/corpus.bend","-o","build/image-comparison/prepare"])
    command("./build/image-comparison/prepare",["+RTS","--threads","1","--gpu","off"])
    command("bend",["tools/image-decoder/probes.bend","-o","build/image-comparison/probes"])
    command("./build/image-comparison/probes",["+RTS","--threads","1","--gpu","off"])
    command("bend",["tools/image-decoder/runtime.bend","-o","build/image-comparison/runtime"])
    command("./build/image-comparison/runtime",["+RTS","--threads","1","--gpu","off"])
    command("bend",["tools/image-decoder/files.bend","-o","build/image-comparison/files"])
    command("./build/image-comparison/files",["+RTS","--threads","1","--gpu","off"])
    command("bend",["tools/image-decoder/mutations.bend","-o","build/image-comparison/mutations"])
    command("./build/image-comparison/mutations",["+RTS","--threads","1","--gpu","off"])
    command("bend",["examples/image-assets.bend","-o","build/image-comparison/example"])
    command("./build/image-comparison/example",["build/image-corpus/june-rgb8.png","+RTS","--threads","1","--gpu","off"])
